import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import { argsSchema, type Args } from "./unions/args.js";
import { descriptionSchema, type Description } from "./unions/description.js";
import { inputSchema, type Input } from "./unions/input.js";
import { returnsSchema, type Returns } from "./unions/returns.js";

/**
 * One task definition from the control channel's `tasks.list` reply.
 *
 * All schemas are JSON Schemas generated by the SDK: `args` describes the task function's
 * parameters (what a stored task's `args` must satisfy); `input`/`returns` describe the agent's I/O
 * types when the task declares them.
 */
export type ManifestTask = {
  id: string;
  description?: Description;
  args?: Args;
  input?: Input;
  returns?: Returns;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const manifestTaskSchema: Schema<ManifestTask> = s.object<ManifestTask>(
  {
    id: s.string(),
    description: s.optional(s.lazy(() => descriptionSchema)),
    args: s.optional(s.lazy(() => argsSchema)),
    input: s.optional(s.lazy(() => inputSchema)),
    returns: s.optional(s.lazy(() => returnsSchema)),
  },
  { additionalProperties: s.json() },
);
